import { basename } from 'node:path';
import { parseCommandLine } from './lib/cli/argParser.mjs';
import { runProcessingChain } from './lib/pipeline.mjs';

export function main(argv = process.argv) {
  const programName = basename(argv[1] ?? 'test19.mjs');
  const parseResult = parseCommandLine(argv.slice(2), programName);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.text);
    return 0;
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.text);
    return parseResult.exitCode;
  }

  const outputs = runProcessingChain(parseResult.values);
  console.log(outputs.phase1_a);
  console.log(outputs.phase1_b);
  console.log(outputs.phase1_c);
  console.log(outputs.phase2_d);
  console.log(outputs.phase2_e);
  console.log(outputs.phase2_f);
  console.log(outputs.phase3_combined);
  console.log(outputs.phase4_nested);
  console.log(outputs.phase5_final);
  return 0;
}

const exitCode = main(process.argv);
if (exitCode !== 0) {
  process.exitCode = exitCode;
}

