import { escapeHtml } from './escape.mjs';

function countBackticks(text, startIndex) {
  let count = 0;
  while (startIndex + count < text.length && text[startIndex + count] === '`') {
    count += 1;
  }
  return count;
}

function findClosingBackticks(text, startIndex, tickCount) {
  let index = startIndex;
  while (index < text.length) {
    if (text[index] !== '`') {
      index += 1;
      continue;
    }

    if (countBackticks(text, index) === tickCount) {
      return index;
    }

    index += 1;
  }

  return -1;
}

function isAllSpaces(text) {
  for (const character of text) {
    if (character !== ' ') {
      return false;
    }
  }
  return true;
}

function normalizeCodeSpanContent(content) {
  if (content.length >= 2 && content[0] === ' ' && content[content.length - 1] === ' ' && !isAllSpaces(content)) {
    return content.slice(1, content.length - 1);
  }
  return content;
}

export function renderInline(text) {
  let result = '';
  let index = 0;

  while (index < text.length) {
    if (text[index] === '`') {
      const tickCount = countBackticks(text, index);
      const closingIndex = findClosingBackticks(text, index + tickCount, tickCount);
      if (closingIndex !== -1) {
        const content = normalizeCodeSpanContent(text.slice(index + tickCount, closingIndex));
        result += `<code>${escapeHtml(content)}</code>`;
        index = closingIndex + tickCount;
        continue;
      }
    }

    result += escapeHtml(text[index]);
    index += 1;
  }

  return result;
}

