    if (startsBlock(lines, currentIndex, config)) {
      break;
    }

    paragraphLines.push(lines[currentIndex]);
    currentIndex += 1;
  }

  return {
    type: 'paragraph',
    html: `<p>${renderInline(paragraphLines.join('\n'))}</p>`,
    nextIndex: currentIndex,
  };
}

function shouldPreserveBlankLineAfter(blockType) {
  return blockType === 'raw_html' || blockType === 'codehilite';
}

function joinBlocks(blocks) {
  if (blocks.length === 0) {
    return '';
  }

  let output = '';
  for (let index = 0; index < blocks.length; index += 1) {
    output += blocks[index].html;
    if (index + 1 >= blocks.length) {
      continue;
    }

    output += '\n';
    if (blocks[index].hadBlankAfter && shouldPreserveBlankLineAfter(blocks[index].type)) {
      output += '\n';
    }
  }

  return output;
}

export function markdownToHtml(source, options = {}) {
  const config = createConfig(options);
  const state = { toc: createTocState() };
  const lines = source.split('\n');
  const blocks = [];
  let index = 0;

  while (index < lines.length && isBlankLine(lines[index])) {
    index += 1;
  }

  while (index < lines.length) {
    let block = parseFencedCode(lines, index, config);
    if (block === null && config.tables && isTableStart(lines, index)) {
      block = parseTable(lines, index);
    }
    if (block === null) {
      const heading = parseHeading(lines[index], config, state);
      if (heading !== null) {
        block = {
          type: heading.type,
          html: heading.html,
          nextIndex: index + 1,
        };
      }
    }
    if (block === null) {
      block = parseRawHtmlBlock(lines, index);
    }
    if (block === null) {
      block = parseParagraph(lines, index, config);
    }

    index = block.nextIndex;
    let hadBlankAfter = false;
    while (index < lines.length && isBlankLine(lines[index])) {
      hadBlankAfter = true;
      index += 1;
    }
    blocks.push({ type: block.type, html: block.html, hadBlankAfter });
  }

  return joinBlocks(blocks);
}

