import { renderInline } from './inline.mjs';

function splitTableRow(line) {
  let text = line.trim();
  if (text.startsWith('|')) {
    text = text.slice(1);
  }
  if (text.endsWith('|')) {
    text = text.slice(0, text.length - 1);
  }

  const cells = text.split('|');
  const normalizedCells = [];
  for (const cell of cells) {
    normalizedCells.push(cell.trim());
  }
  return normalizedCells;
}

function isSeparatorCell(cell) {
  if (cell.length === 0) {
    return false;
  }

  let hasHyphen = false;
  for (const character of cell) {
    if (character === '-') {
      hasHyphen = true;
      continue;
    }

    if (character === ':' || character === ' ') {
      continue;
    }

    return false;
  }

  return hasHyphen;
}

function isTableRow(line) {
  return line.includes('|');
}

export function isTableStart(lines, index) {
  if (index + 1 >= lines.length) {
    return false;
  }

  const headerLine = lines[index];
  const separatorLine = lines[index + 1];

  if (!isTableRow(headerLine) || !isTableRow(separatorLine)) {
    return false;
  }

  const separatorCells = splitTableRow(separatorLine);
  if (separatorCells.length === 0) {
    return false;
  }

  for (const cell of separatorCells) {
    if (!isSeparatorCell(cell)) {
      return false;
    }
  }

  return true;
}

function renderTableCells(tagName, cells) {
  const parts = [];
  for (const cell of cells) {
    parts.push(`<${tagName}>${renderInline(cell)}</${tagName}>`);
  }
  return parts.join('\n');
}

export function parseTable(lines, index) {
  const headerCells = splitTableRow(lines[index]);
  const bodyRows = [];
  let currentIndex = index + 2;

  while (currentIndex < lines.length && lines[currentIndex].trim().length > 0 && isTableRow(lines[currentIndex])) {
    bodyRows.push(splitTableRow(lines[currentIndex]));
    currentIndex += 1;
  }

  const parts = [];
  parts.push('<table>');
  parts.push('<thead>');
  parts.push('<tr>');
  parts.push(renderTableCells('th', headerCells));
  parts.push('</tr>');
  parts.push('</thead>');
  parts.push('<tbody>');
  for (const row of bodyRows) {
    parts.push('<tr>');
    parts.push(renderTableCells('td', row));
    parts.push('</tr>');
  }
  parts.push('</tbody>');
  parts.push('</table>');

  return {
    type: 'table',
    html: parts.join('\n'),
    nextIndex: currentIndex,
  };
}

