import { escapeHtml, escapeHtmlAttribute, escapeHighlightedText } from './escape.mjs';

const PYTHON_KEYWORDS = new Set([
  'False',
  'None',
  'True',
  'and',
  'as',
  'assert',
  'async',
  'await',
  'break',
  'class',
  'continue',
  'def',
  'del',
  'elif',
  'else',
  'except',
  'finally',
  'for',
  'from',
  'if',
  'import',
  'in',
  'is',
  'lambda',
  'nonlocal',
  'not',
  'or',
  'pass',
  'raise',
  'return',
  'try',
  'while',
  'with',
  'yield',
]);

const PYTHON_BUILTINS = new Set([
  'dict',
  'float',
  'int',
  'len',
  'list',
  'open',
  'print',
  'range',
  'set',
  'str',
  'tuple',
  'type',
]);

const JAVASCRIPT_KEYWORDS = new Set([
  'class',
  'const',
  'else',
  'export',
  'function',
  'if',
  'import',
  'let',
  'new',
  'return',
  'var',
]);

const BASH_BUILTINS = new Set([
  'cd',
  'echo',
  'exit',
  'export',
  'printf',
  'pwd',
  'read',
]);

function renderSpan(className, htmlText) {
  return `<span class="${className}">${htmlText}</span>`;
}

function isIdentifierStart(character) {
  return (character >= 'a' && character <= 'z') || (character >= 'A' && character <= 'Z') || character === '_';
}

function isIdentifierPart(character) {
  return isIdentifierStart(character) || (character >= '0' && character <= '9');
}

function isJavascriptIdentifierPart(character) {
  return isIdentifierPart(character) || character === '$';
}

function isHtmlTagNamePart(character) {
  return isIdentifierPart(character);
}

function isBashVariablePart(character) {
  return isIdentifierPart(character);
}

function isPunctuation(character) {
  return '()[]{}:.,;+-*/%=&|<>!'.includes(character);
}

function splitCodeLines(code) {
  const lines = code.split('\n');
  const endsWithNewline = code.length > 0 && code[code.length - 1] === '\n';
  if (endsWithNewline && lines.length > 0) {
    lines.pop();
  }
  return { lines, endsWithNewline };
}

function renderWithLines(code, renderLine) {
  const { lines, endsWithNewline } = splitCodeLines(code);
  let result = '';

  for (let index = 0; index < lines.length; index += 1) {
    result += renderLine(lines[index]);
    if (index + 1 < lines.length || endsWithNewline) {
      result += '\n';
    }
  }

  return result;
}

function readQuotedString(text, startIndex) {
  const quote = text[startIndex];
  let index = startIndex + 1;
  while (index < text.length) {
    const character = text[index];
    if (character === '\\') {
      index += 2;
      continue;
    }

    if (character === quote) {
      index += 1;
      break;
    }

    index += 1;
  }

  return {
    value: text.slice(startIndex, index),
    nextIndex: index,
  };
}

function renderPythonLine(line) {
  let result = '';
  let index = 0;
  let pendingNameClass = '';

  while (index < line.length && line[index] === ' ') {
    result += ' ';
    index += 1;
  }

  while (index < line.length) {
    const character = line[index];

    if (character === ' ') {
      let endIndex = index;
      while (endIndex < line.length && line[endIndex] === ' ') {
        endIndex += 1;
      }
      result += renderSpan('w', escapeHtml(line.slice(index, endIndex)));
      index = endIndex;
      continue;
    }

    if (character === '\'' || character === '"') {
      const token = readQuotedString(line, index);
      result += renderSpan(character === '\'' ? 's1' : 's2', escapeHighlightedText(token.value));
      index = token.nextIndex;
      pendingNameClass = '';
      continue;
    }

    if (isIdentifierStart(character)) {
      let endIndex = index + 1;
      while (endIndex < line.length && isIdentifierPart(line[endIndex])) {
        endIndex += 1;
      }

      const word = line.slice(index, endIndex);
      if (pendingNameClass.length > 0) {
        result += renderSpan(pendingNameClass, escapeHtml(word));
        pendingNameClass = '';
      } else if (PYTHON_KEYWORDS.has(word)) {
        result += renderSpan('k', escapeHtml(word));
        if (word === 'def') {
          pendingNameClass = 'nf';
        } else if (word === 'class') {
          pendingNameClass = 'nc';
        }
      } else if (PYTHON_BUILTINS.has(word)) {
        result += renderSpan('nb', escapeHtml(word));
      } else {
        result += escapeHtml(word);
      }

      index = endIndex;
      continue;
    }

    if (isPunctuation(character)) {
      let endIndex = index + 1;
      while (endIndex < line.length && isPunctuation(line[endIndex])) {
        endIndex += 1;
      }
      result += renderSpan('p', escapeHtml(line.slice(index, endIndex)));
      index = endIndex;
      pendingNameClass = '';
      continue;
    }

    result += escapeHtml(character);
    index += 1;
    pendingNameClass = '';
  }

  return result;
}

function renderJavascriptLine(line) {
  let result = '';
  let index = 0;

  while (index < line.length && line[index] === ' ') {
    result += ' ';
    index += 1;
  }

  while (index < line.length) {
    const character = line[index];

    if (character === ' ') {
      let endIndex = index;
      while (endIndex < line.length && line[endIndex] === ' ') {
        endIndex += 1;
      }
      result += renderSpan('w', escapeHtml(line.slice(index, endIndex)));
      index = endIndex;
      continue;
    }

    if (character === '\'' || character === '"') {
      const token = readQuotedString(line, index);
      result += renderSpan(character === '\'' ? 's1' : 's2', escapeHighlightedText(token.value));
      index = token.nextIndex;
      continue;
    }

    if (isJavascriptIdentifierPart(character)) {
      let endIndex = index + 1;
      while (endIndex < line.length && isJavascriptIdentifierPart(line[endIndex])) {
        endIndex += 1;
      }
      const word = line.slice(index, endIndex);
      if (JAVASCRIPT_KEYWORDS.has(word)) {
        result += renderSpan('k', escapeHtml(word));
      } else {
        result += renderSpan('nx', escapeHtml(word));
      }
      index = endIndex;
      continue;
    }

    if (isPunctuation(character)) {
      let endIndex = index + 1;
      while (endIndex < line.length && isPunctuation(line[endIndex])) {
        endIndex += 1;
      }
      result += renderSpan('p', escapeHtml(line.slice(index, endIndex)));
      index = endIndex;
      continue;
    }

    result += escapeHtml(character);
    index += 1;
  }

  return result;
}

function renderHtmlLine(line) {
  let result = '';
  let index = 0;

  while (index < line.length) {
    const character = line[index];
    if (character !== '<') {
      result += escapeHtml(character);
      index += 1;
      continue;
    }

    if (index + 1 < line.length && line[index + 1] === '/') {
      result += renderSpan('p', '&lt;/');
      index += 2;
    } else {
      result += renderSpan('p', '&lt;');
      index += 1;
    }

    const tagNameStart = index;
    while (index < line.length && isHtmlTagNamePart(line[index])) {
      index += 1;
    }

    if (index > tagNameStart) {
      result += renderSpan('nt', escapeHtml(line.slice(tagNameStart, index)));
    }

    while (index < line.length && line[index] !== '>') {
      result += escapeHtml(line[index]);
      index += 1;
    }

    if (index < line.length && line[index] === '>') {
      result += renderSpan('p', '&gt;');
      index += 1;
    }
  }

  return result;
}

function renderBashLine(line) {
  let result = '';
  let index = 0;

  while (index < line.length && line[index] === ' ') {
    result += ' ';
    index += 1;
  }

  while (index < line.length) {
    const character = line[index];
    if (character === ' ') {
      let endIndex = index;
      while (endIndex < line.length && line[endIndex] === ' ') {
        endIndex += 1;
      }
      result += renderSpan('w', escapeHtml(line.slice(index, endIndex)));
      index = endIndex;
      continue;
    }

    if (character === '$') {
      let endIndex = index + 1;
      while (endIndex < line.length && isBashVariablePart(line[endIndex])) {
        endIndex += 1;
      }

      const token = line.slice(index, endIndex);
      result += renderSpan('nv', escapeHtml(token));
      index = endIndex;
      continue;
    }

    let endIndex = index;
    while (endIndex < line.length && line[endIndex] !== ' ') {
      endIndex += 1;
    }

    const token = line.slice(index, endIndex);
    if (BASH_BUILTINS.has(token)) {
      result += renderSpan('nb', escapeHtml(token));
    } else {
      result += escapeHtml(token);
    }
    index = endIndex;
  }

  return result;
}

function normalizeLanguage(language) {
  const trimmed = language.trim().toLowerCase();
  if (trimmed === 'js') {
    return 'javascript';
  }
  if (trimmed === 'py') {
    return 'python';
  }
  if (trimmed === 'sh' || trimmed === 'shell') {
    return 'bash';
  }
  return trimmed;
}

function renderHighlightedCode(code, language) {
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage === 'python') {
    return renderWithLines(code, renderPythonLine);
  }
  if (normalizedLanguage === 'javascript') {
    return renderWithLines(code, renderJavascriptLine);
  }
  if (normalizedLanguage === 'html') {
    return renderWithLines(code, renderHtmlLine);
  }
  if (normalizedLanguage === 'bash') {
    return renderWithLines(code, renderBashLine);
  }
  return escapeHtml(code);
}

function ensureTrailingNewline(content) {
  if (content.length === 0 || content.endsWith('\n')) {
    return content;
  }
  return `${content}\n`;
}

export function renderFencedCodeBlock(content, language, useCodeHilite) {
  const normalizedContent = ensureTrailingNewline(content);
  if (useCodeHilite) {
    const highlighted = renderHighlightedCode(normalizedContent, language);
    return {
      type: 'codehilite',
      html: `<div class="codehilite"><pre><span></span><code>${highlighted}</code></pre></div>`,
    };
  }

  let classAttribute = '';
  const trimmedLanguage = language.trim();
  if (trimmedLanguage.length > 0) {
    classAttribute = ` class="language-${escapeHtmlAttribute(trimmedLanguage)}"`;
  }

  return {
    type: 'code',
    html: `<pre><code${classAttribute}>${escapeHtml(normalizedContent)}</code></pre>`,
  };
}

