import { markdownToHtml } from './markdown/engine.mjs';

export function runProcessingChain(args) {
  const phase1_a = markdownToHtml(args.a);
  const phase1_b = markdownToHtml(args.b);
  const phase1_c = markdownToHtml(args.c);

  const phase2_d = markdownToHtml(args.d, { extensions: ['extra', 'tables'] });
  const phase2_e = markdownToHtml(args.e, { extensions: ['codehilite', 'fenced_code'] });
  const phase2_f = markdownToHtml(args.f, { extensions: ['toc'] });

  const phase3_combined = markdownToHtml(`
# Combined Document

## Section A
${phase1_a}

## Section B
${phase1_b}

## Section C
${phase1_c}

## Section D
${phase2_d}

## Section E
${phase2_e}

## Section F
${phase2_f}
`);

  const phase4_nested = markdownToHtml(`<article>${phase3_combined}</article>`);

  const phase5_final = markdownToHtml(
    `${args.a}\n\n${args.b}\n\n${args.c}\n\n${args.d}\n\n${args.e}\n\n${args.f}`,
    {
      extensions: ['extra', 'tables', 'codehilite', 'fenced_code', 'toc'],
      output_format: 'xhtml',
    },
  );

  return {
    phase1_a,
    phase1_b,
    phase1_c,
    phase2_d,
    phase2_e,
    phase2_f,
    phase3_combined,
    phase4_nested,
    phase5_final,
  };
}

