const REQUIRED_OPTIONS = ['a', 'b', 'c', 'd', 'e', 'f'];

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}

Markdown processing with transformation chain

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
  --f F
`;
}

function createResult(kind, payload) {
  return { kind, ...payload };
}

function isKnownOption(token) {
  if (!token.startsWith('--')) {
    return false;
  }

  if (token.length !== 3) {
    return false;
  }

  const optionName = token.slice(2);
  return REQUIRED_OPTIONS.includes(optionName);
}

function isHelpOption(token) {
  if (token === '-h' || token === '--help') {
    return true;
  }

  if (!token.startsWith('--')) {
    return false;
  }

  const name = token.slice(2);
  if (name.length === 0) {
    return false;
  }

  return '--help'.startsWith(token);
}

function isOptionLikeValue(token) {
  if (!token.startsWith('-')) {
    return false;
  }

  if (token.length === 1) {
    return false;
  }

  let digitCount = 0;
  for (let index = 1; index < token.length; index += 1) {
    const character = token[index];
    if (character >= '0' && character <= '9') {
      digitCount += 1;
      continue;
    }

    if (character === '.') {
      continue;
    }

    return true;
  }

  return digitCount === 0;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}
${programName}: error: ${message}
`;
}

function splitLongOption(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { optionToken: token, hasInlineValue: false, inlineValue: '' };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function buildMissingRequiredMessage(values) {
  const missing = [];
  for (const optionName of REQUIRED_OPTIONS) {
    if (!(optionName in values)) {
      missing.push(`--${optionName}`);
    }
  }

  return `the following arguments are required: ${missing.join(', ')}`;
}

export function parseCommandLine(argv, programName) {
  const values = {};
  const unknownTokens = [];
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];
    const longOption = splitLongOption(token);

    if (token === '-h') {
      return createResult('help', { text: buildHelp(programName), exitCode: 0, stream: 'stdout' });
    }

    if (longOption.optionToken === '--help') {
      if (longOption.hasInlineValue) {
        return createResult('error', {
          text: buildError(programName, `argument -h/--help: ignored explicit argument '${longOption.inlineValue}'`),
          exitCode: 2,
          stream: 'stderr',
        });
      }

      return createResult('help', { text: buildHelp(programName), exitCode: 0, stream: 'stdout' });
    }

    if (isHelpOption(longOption.optionToken)) {
      if (longOption.hasInlineValue) {
        return createResult('error', {
          text: buildError(programName, `argument -h/--help: ignored explicit argument '${longOption.inlineValue}'`),
          exitCode: 2,
          stream: 'stderr',
        });
      }

      return createResult('help', { text: buildHelp(programName), exitCode: 0, stream: 'stdout' });
    }

    if (isKnownOption(longOption.optionToken)) {
      const optionName = longOption.optionToken.slice(2);
      if (longOption.hasInlineValue) {
        values[optionName] = longOption.inlineValue;
        index += 1;
        continue;
      }

      if (index + 1 >= argv.length || isOptionLikeValue(argv[index + 1])) {
        return createResult('error', {
          text: buildError(programName, `argument ${longOption.optionToken}: expected one argument`),
          exitCode: 2,
          stream: 'stderr',
        });
      }

      values[optionName] = argv[index + 1];
      index += 2;
      continue;
    }

    unknownTokens.push(token);
    index += 1;
  }

  if (Object.keys(values).length !== REQUIRED_OPTIONS.length) {
    return createResult('error', {
      text: buildError(programName, buildMissingRequiredMessage(values)),
      exitCode: 2,
      stream: 'stderr',
    });
  }

  if (unknownTokens.length > 0) {
    return createResult('error', {
      text: buildError(programName, `unrecognized arguments: ${unknownTokens.join(' ')}`),
      exitCode: 2,
      stream: 'stderr',
    });
  }

  return createResult('ok', { values, exitCode: 0, stream: 'stdout' });
}

export function getRequiredOptionNames() {
  return [...REQUIRED_OPTIONS];
}

