function isAsciiLetter(character) {
  return (character >= 'a' && character <= 'z') || (character >= 'A' && character <= 'Z');
}

function isAsciiDigit(character) {
  return character >= '0' && character <= '9';
}

function toLowerAscii(character) {
  if (character >= 'A' && character <= 'Z') {
    return String.fromCharCode(character.charCodeAt(0) + 32);
  }

  return character;
}

function isSeparatorCharacter(character) {
  return character === ' ' || character === '-' || character === '_';
}

function slugify(text) {
  let result = '';
  let previousWasSeparator = false;

  for (const character of text) {
    if (isAsciiLetter(character)) {
      result += toLowerAscii(character);
      previousWasSeparator = false;
      continue;
    }

    if (isAsciiDigit(character)) {
      result += character;
      previousWasSeparator = false;
      continue;
    }

    if (isSeparatorCharacter(character)) {
      if (result.length > 0 && !previousWasSeparator) {
        result += '-';
        previousWasSeparator = true;
      }
    }
  }

  if (result.endsWith('-')) {
    result = result.slice(0, result.length - 1);
  }

  return result;
}

export function createTocState() {
  return { usedIds: new Set() };
}

export function buildHeadingId(text, tocState) {
  const base = slugify(text.trim());

  if (base.length === 0) {
    let counter = 1;
    while (tocState.usedIds.has(`_${counter}`)) {
      counter += 1;
    }

    const identifier = `_${counter}`;
    tocState.usedIds.add(identifier);
    return identifier;
  }

  if (!tocState.usedIds.has(base)) {
    tocState.usedIds.add(base);
    return base;
  }

  let suffix = 1;
  while (tocState.usedIds.has(`${base}_${suffix}`)) {
    suffix += 1;
  }

  const identifier = `${base}_${suffix}`;
  tocState.usedIds.add(identifier);
  return identifier;
}

