function escapeCharacter(character, escapeQuotes, escapeApostrophes) {
  if (character === '&') {
    return '&amp;';
  }

  if (character === '<') {
    return '&lt;';
  }

  if (character === '>') {
    return '&gt;';
  }

  if (escapeQuotes && character === '"') {
    return '&quot;';
  }

  if (escapeApostrophes && character === '\'') {
    return '&#39;';
  }

  return character;
}

export function escapeHtml(text) {
  let result = '';
  for (const character of text) {
    result += escapeCharacter(character, false, false);
  }
  return result;
}

export function escapeHtmlAttribute(text) {
  let result = '';
  for (const character of text) {
    result += escapeCharacter(character, true, true);
  }
  return result;
}

export function escapeHighlightedText(text) {
  let result = '';
  for (const character of text) {
    result += escapeCharacter(character, false, true);
  }
  return result;
}

